import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`accounting-audit`,heroTitle:`Land more clients for your firm in minutes`,heroSubtitle:`Perplexity Computer audits your website, reviews, and local SEO, then delivers a plan to win more retainer clients — automatically.`,inputUrlCta:`Audit my firm`,inputUrlPlaceholder:`yourfirm.com`,inputUrlPrefill:`Go to {url} and run a full digital audit for this accounting firm. (1) Audit the website for service pages, lead capture forms, mobile experience, and local SEO for tax and accounting search terms. (2) Review the Google Business Profile for completeness, reviews, and response rate. (3) Analyze Google reviews and Clutch profile for recurring client feedback on responsiveness, expertise, and pricing. (4) Benchmark against the top 5 local accounting firms for review volume, service breadth, and online presence. (5) Deliver an actionable plan to rank higher for tax and accounting searches, convert more website visitors into consultations, and increase retainer revenue — with specific fixes prioritized by client acquisition impact.`,heroOverlaySteps:[`Auditing your website for service pages, lead capture, and tax keyword SEO`,`Analyzing Google reviews and Clutch profile for client sentiment and trust gaps`,`Benchmarking against the top 5 accounting firms in your area`,`Client acquisition plan with SEO fixes, review templates, and retainer strategy — ready to execute`],generatingSteps:[`Visiting {url} to audit your website, services, and lead capture flow`,`Designing an agent to analyze client reviews and local search rankings`,`Configuring competitor benchmarking and service gap analysis pipelines`,`Setting up growth plan report with client acquisition and retainer recommendations`],featureSectionTitle:`From website to client pipeline`,featureCardTitles:[`Connects to your firm stack`,`Fixes that win retainer clients`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Google Analytics, Gmail, QuickBooks — Computer plugs into your tools so audits, client tracking, and follow-ups happen in one workflow.`,`Service page rewrites. Lead capture improvements. Local SEO fixes. Review response templates. Computer delivers changes ranked by client acquisition impact.`],capabilitySectionTitle:`Your client acquisition team, on autopilot`,capabilitySectionSubtitle:`Paste your firm URL, get back a complete client acquisition plan.`,capabilityCards:[{title:`Service Page & SEO Audit`,description:`Computer can audit every service page for tax and accounting keyword coverage, lead capture friction, and local SEO — and flag what is costing you consultations.`},{title:`Client Review Analysis`,description:`Computer can analyze Google reviews and Clutch profiles to surface feedback on responsiveness, expertise, pricing, and turnaround time — with trends by season.`},{title:`Tax Season Positioning`,description:`Computer can analyze how top firms position for tax season — service bundles, landing pages, and ad copy — and show where you are leaving clients on the table.`},{title:`Connect Your Tools`,description:`Computer can read from Google Sheets, Google Analytics, Gmail, and QuickBooks — build workflows across your firm operations.`},{title:`Knows Your Firm`,description:`Computer can remember your services, client types, tax specialties, and past audits across sessions — so every review builds on what came before.`},{title:`Review & Ranking Alerts`,description:`Computer can watch your Google reviews and Clutch profile weekly — and alert you when a client review needs a response or your local ranking drops.`}]});export{t as default};
